enum UserApprovalStatus { approved, rejected, pending,}extension UserApprovalStatusHelper on UserApprovalStatus { static final _id = <UserApprovalStatus, int>{  UserApprovalStatus.approved: 1,  UserApprovalStatus.rejected: 2,  UserApprovalStatus.pending: 3, }; int? get id => _id[this]; static final _name = <UserApprovalStatus, String>{  UserApprovalStatus.approved: 'Approved',  UserApprovalStatus.rejected: 'Rejected',  UserApprovalStatus.pending: 'Pending', }; String get name => _name[this] ?? '';}enum OrganizationType { indianRailways, contractor,}extension OrganizationTypeHelper on OrganizationType { static final _id = <OrganizationType, int>{  OrganizationType.indianRailways: 1,  OrganizationType.contractor: 2, }; int? get id => _id[this]; static final _name = <OrganizationType, String>{  OrganizationType.indianRailways: 'Indian Railways',  OrganizationType.contractor: 'Contractor', }; String get name => _name[this] ?? '';}enum DeviceStatus { inactive, active, pending, registration, underMaintenance, retired,}extension DeviceStatusHelper on DeviceStatus { static final _id = <DeviceStatus, int>{  DeviceStatus.inactive: 0,  DeviceStatus.active: 1,  DeviceStatus.pending: 2,  DeviceStatus.registration: 3,  DeviceStatus.underMaintenance: 4,  DeviceStatus.retired: 5, }; int? get id => _id[this]; static final _name = <DeviceStatus, String>{  DeviceStatus.inactive: 'Inactive',  DeviceStatus.active: 'Active',  DeviceStatus.pending: 'Pending',  DeviceStatus.registration: 'Registration',  DeviceStatus.underMaintenance: 'Under Maintenance',  DeviceStatus.retired: 'Retired', }; String get name => _name[this] ?? ''; static DeviceStatus fromId(int? id) {  if (id == null) return DeviceStatus.inactive;  return _id.entries      .firstWhere(       (entry) => entry.value == id,   orElse: () =>   const MapEntry(DeviceStatus.inactive, 0),  )      .key; } static DeviceStatus fromBool(bool? isActive) {  if (isActive == null) return DeviceStatus.inactive;  if(isActive) {   return DeviceStatus.active;  } else {   return DeviceStatus.inactive;  } }}enum DataTypes { number, decimal, percentage, binary,}extension DataTypesHelper on DataTypes { static final _id = <DataTypes, int>{  DataTypes.number: 0,  DataTypes.decimal: 1,  DataTypes.percentage: 2,  DataTypes.binary: 3, }; int? get id => _id[this]; static final _name = <DataTypes, String>{  DataTypes.number: 'Number',  DataTypes.decimal: 'Decimal',  DataTypes.percentage: 'Percentage',  DataTypes.binary: 'Binary', }; String get name => _name[this] ?? ''; static DataTypes fromId(int? id) {  if (id == null) return DataTypes.number;  return _id.entries      .firstWhere(       (entry) => entry.value == id,   orElse: () =>   const MapEntry(DataTypes.number, 0),  )      .key; }}enum ConditionConnectors { none, and, or,}extension ConditionConnectorsHelper on ConditionConnectors { static final _id = <ConditionConnectors, int>{  ConditionConnectors.none: 0,  ConditionConnectors.and: 1,  ConditionConnectors.or: 2, }; int? get id => _id[this]; static final _name = <ConditionConnectors, String>{  ConditionConnectors.none: 'NONE',  ConditionConnectors.and: 'AND',  ConditionConnectors.or: 'OR', }; String get name => _name[this] ?? ''; static ConditionConnectors fromId(int? id) {  if (id == null) return ConditionConnectors.none;  return _id.entries      .firstWhere(       (entry) => entry.value == id,   orElse: () =>   const MapEntry(ConditionConnectors.none, 0),  )      .key; }}enum ChartViewType { hour, day, week, month,}